import{_ as t,o as i,c as n,ae as o}from"./chunks/framework.Czhw_PXq.js";const p=JSON.parse('{"title":"ADR 010: Security Hardening Strategy (Defense in Depth)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/010-security-hardening.md","filePath":"adr/010-security-hardening.md"}'),r={name:"adr/010-security-hardening.md"};function a(s,e,l,d,c,g){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-010-security-hardening-strategy-defense-in-depth" tabindex="-1">ADR 010: Security Hardening Strategy (Defense in Depth) <a class="header-anchor" href="#adr-010-security-hardening-strategy-defense-in-depth" aria-label="Permalink to &quot;ADR 010: Security Hardening Strategy (Defense in Depth)&quot;">​</a></h1><p><strong>Date</strong>: 2026-01-25 <strong>Status</strong>: Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>As a system handling public tender documents (&quot;Pliegos&quot;), strict security is non-negotiable. Initial MVP implementation lacked robust protection against common vectors like brute-force attacks, malicious file uploads, and weak credentials.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have adopted a <strong>Defense-in-Depth</strong> strategy covering multiple layers:</p><ol><li><p><strong>Network/Transport Layer</strong>:</p><ul><li><strong>Rate Limiting</strong>: Implemented <code>express-rate-limit</code> on <code>/api/auth/login</code>. Policy: Max 3 attempts per 15 minutes to block brute-force.</li><li><strong>Secure Headers</strong>: Enforced via <code>Helmet.js</code> (CSP, HSTS).</li><li><strong>CORS</strong>: Strict allowed origins from <code>.env</code>.</li></ul></li><li><p><strong>Input Validation Layer</strong>:</p><ul><li><strong>File Uploads</strong>: Double validation for PDF ingestion. <ul><li><em>Layer 1 (Multer)</em>: <code>fileFilter</code> rejects non-PDF MIME types immediately.</li><li><em>Layer 2 (Controller)</em>: <code>Zod</code> validates file structure and size (Max 50MB) before business logic execution.</li></ul></li></ul></li><li><p><strong>Credential &amp; Session Layer</strong>:</p><ul><li><strong>Password Complexity</strong>: Enforced Min 8 chars, 1 Uppercase, 1 Number, 1 Special Char via Zod Regex.</li><li><strong>JWT Secret Standardization</strong>: Centralized <code>JWT_SECRET_FALLBACK</code> in <code>constants.ts</code> to prevent token mismatch errors during local development where env vars might be missing.</li><li><strong>Defensive Token Loading</strong>: Frontend <code>AuthContext</code> implements a filtering layer that rejects literal <code>&quot;undefined&quot;</code> strings in localStorage, preventing accidental 401 loops in the browser.</li></ul></li><li><p><strong>Observability &amp; Compliance</strong>:</p><ul><li><strong>Sentry</strong>: Integrated for real-time error tracking (Backend + Frontend).</li><li><strong>Snyk</strong>: Added dependency vulnerability scanning (<code>npm run security:scan</code>).</li><li><strong>Husky</strong>: Pre-commit hooks enforce <code>lint</code> and <code>test</code> to prevent bad code from entering the repo.</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>OWASP Compliance</strong>: Mitigates Top 10 risks (Broken Auth, Security Misconfig, Vulnerable Components).</li><li><strong>Resilience</strong>: Service cannot be easily DoS&#39;d via login flooding.</li><li><strong>Trust</strong>: User data and uploaded documents are handled with rigor.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>UX Friction</strong>: Strong passwords and strict file types might annoy some legitimate users (mitigated via clear UI hints).</li><li><strong>Dev Friction</strong>: Pre-commit hooks slow down the commit process slightly (trade-off for quality).</li></ul>',12)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
